#define SWAP(x, y, t) ((t)=(x), (x)=(y), (y)=(t))

void sort(int list[ ], int n)

{

 int i, j, least, temp;

 for (i = 0; i < n - 1; i++) {

 least = i;

 for (j = i + 1; j < n; j++) 

 if (list[j] < list[least]) least = j;

 SWAP(list[i], list[least], temp);

 }

}

#include <stdio.h>
int i;
int RecFunc(int n)
{
i++;
if (n <= 1)
return 1;
else
return RecFunc(n-1) + RecFunc(n-2);
}
int main()
{
int result;
i = 0;
result = RecFunc(5);
printf("%d, %d\n", i, result);
}

